(async () => {
  const { env } = process;
  const inputPath = env.INPUT_PATH;
  const outputPath = env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  const width = env.WIDTH ? Number(env.WIDTH) : undefined;
  const height = env.HEIGHT ? Number(env.HEIGHT) : undefined;
  globalThis._sharp_state = { inputPath, outputPath, width, height };
})();

(async () => {
  const { default: sharp } = await import('sharp');
  const { inputPath, outputPath, width, height } = globalThis._sharp_state;
  let pipeline = sharp(inputPath);
  if (width !== undefined || height !== undefined) {
    pipeline = pipeline.resize({ width, height });
  }
  await pipeline.toFile(outputPath);
  globalThis._sharp_result = { outputPath };
})();

(async () => {
  const result = globalThis._sharp_result;
  if (!result) throw new Error('Execute step did not produce a result');
  console.log(JSON.stringify({ output_path: result.outputPath }));
})();
